DROP TABLE IF EXISTS `control_calidad`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `control_calidad` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_proveedor` int NOT NULL,
  `id_obra` int NOT NULL,
  `descripcion_servicio` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `monto_cotizado` decimal(12,2) DEFAULT NULL,
  `monto_autorizado` decimal(12,2) DEFAULT NULL,
  `moneda` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT 'MXN',
  `estado` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cotizado',
  `archivo_cotizacion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nombre_cotizacion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `archivo_cfdi` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nombre_cfdi` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
