  `nombre_factura` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `archivo_resultados` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nombre_resultados` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_cotizacion` datetime DEFAULT CURRENT_TIMESTAMP,
  `fecha_autorizacion` datetime DEFAULT NULL,
  `fecha_pago` datetime DEFAULT NULL,
  `fecha_factura` datetime DEFAULT NULL,
  `fecha_resultados` datetime DEFAULT NULL,
  `autorizado_por` int DEFAULT NULL,
  `pagado_por` int DEFAULT NULL,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `periodo_desde` date DEFAULT NULL,
  `periodo_hasta` date DEFAULT NULL,
  `creado_en` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_prov` (`id_proveedor`),
  KEY `idx_obra` (`id_obra`),
  KEY `idx_estado` (`estado`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
