--
-- Table structure for table `nomina`
--

DROP TABLE IF EXISTS `nomina`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `nomina` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_empleado` int NOT NULL,
  `semana` varchar(20) NOT NULL COMMENT 'Ej: 2026-W28',
  `fecha_inicio` date NOT NULL,
  `fecha_fin` date NOT NULL,
  `dias_trabajados` int NOT NULL DEFAULT '0',
  `horas_normales` decimal(6,2) DEFAULT '0.00',
  `horas_extra` decimal(6,2) DEFAULT '0.00',
  `salario_base` decimal(10,2) DEFAULT '0.00' COMMENT 'salario_diario * dias_trabajados',
  `sueldo_semanal` decimal(10,2) DEFAULT '0.00',
  `pago_horas_extra` decimal(10,2) DEFAULT '0.00',
  `bonos` decimal(10,2) DEFAULT '0.00',
  `devengado` decimal(10,2) DEFAULT '0.00',
  `descuento_isr` decimal(10,2) DEFAULT '0.00',
  `descuento_imss` decimal(10,2) DEFAULT '0.00',
  `descuento_infonavit` decimal(10,2) DEFAULT '0.00',
  `otros_descuentos` decimal(10,2) DEFAULT '0.00',
  `descripcion_otros_desc` varchar(255) DEFAULT NULL,
  `total_descuentos` decimal(10,2) DEFAULT '0.00',
  `deducciones` decimal(10,2) DEFAULT '0.00',
  `total_pagar` decimal(10,2) DEFAULT '0.00',
  `monto_empresa` decimal(10,2) DEFAULT '0.00',
  `validado_por` int DEFAULT NULL,
  `nombre_validador` varchar(150) DEFAULT NULL,
  `fecha_validacion` datetime DEFAULT NULL,
  `observaciones` text,
  `estatus` enum('borrador','aprobada','pagada') NOT NULL DEFAULT 'borrador',
  `generado_por` int DEFAULT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_empleado_semana` (`id_empleado`,`semana`),
  KEY `idx_semana` (`semana`),
  KEY `idx_estatus` (`estatus`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
