--
-- Table structure for table `reportes_combustible`
--

DROP TABLE IF EXISTS `reportes_combustible`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reportes_combustible` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `codigo_eco` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_equipo` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `marca` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_obra` int DEFAULT NULL,
  `fecha` date NOT NULL,
  `semana` smallint DEFAULT NULL COMMENT 'Semana operativa',
  `operador` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `litros_cargados` decimal(8,2) DEFAULT NULL COMMENT 'Reportado/ticket (manual)',
  `litros_telemetria` decimal(8,2) DEFAULT NULL COMMENT 'Consumo medido por telemetría',
  `litros_faltantes` decimal(8,2) DEFAULT NULL COMMENT 'cargados - telemetría',
  `desviacion_pct` decimal(6,2) DEFAULT NULL,
  `semaforo` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'OK' COMMENT 'OK|Revisar|Alerta|Fraude Probable',
  `horas_maquina` decimal(8,2) DEFAULT NULL,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `justificado` tinyint(1) NOT NULL DEFAULT '0',
  `registrado_por` int DEFAULT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tipo_combustible` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'diesel',
  `costo_total` decimal(12,2) DEFAULT NULL,
  `horometro_inicial` decimal(10,2) DEFAULT NULL,
  `horometro_final` decimal(10,2) DEFAULT NULL,
  `costo_por_litro` decimal(10,2) DEFAULT NULL,
  `lt_por_hr` decimal(10,2) DEFAULT NULL,
  `costo_por_hr` decimal(10,2) DEFAULT NULL,
  `frente_trabajo` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `actividad` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `origen_carga` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `responsable` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `folio_ticket` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `odometro_inicial` decimal(10,2) DEFAULT NULL,
  `odometro_final` decimal(10,2) DEFAULT NULL,
  `km_recorridos` decimal(10,2) DEFAULT NULL,
  `km_por_litro` decimal(10,3) DEFAULT NULL,
  `costo_por_km` decimal(10,2) DEFAULT NULL,
  `destino` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_semaforo` (`semaforo`),
  KEY `idx_fecha` (`fecha`),
  KEY `idx_obra` (`id_obra`)
) ENGINE=InnoDB AUTO_INCREMENT=5571 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
