--
-- Table structure for table `utilizacion`
--

DROP TABLE IF EXISTS `utilizacion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `utilizacion` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `codigo_eco` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `serie` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nombre_equipo` text COLLATE utf8mb4_unicode_ci,
  `marca` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `modelo` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha` date NOT NULL,
  `litros_hora` decimal(8,4) DEFAULT NULL,
  `litros_consumidos` decimal(8,2) DEFAULT NULL,
  `horas_maquina` decimal(8,2) DEFAULT NULL,
  `horas_ralenti` decimal(8,2) DEFAULT NULL,
  `ralenti_porcentaje` decimal(5,2) DEFAULT NULL COMMENT '% horas en ralentí',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_eco_fecha` (`codigo_eco`,`fecha`),
  KEY `idx_eco` (`codigo_eco`),
  KEY `idx_fecha` (`fecha`)
) ENGINE=InnoDB AUTO_INCREMENT=1039 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

